data.query:
query RCVKPIs(
  $df: DateTime $dt: DateTime
  $sd: DateTime $ed: DateTime
) {
  linesReceivedToday: receiptLine(where: {_and: [{createdAt:{_gte:$sd}}, {createdAt:{_lte:$ed}}]}) { total }
  linesReceivedMonth: receiptLine(where: {_and: [{createdAt:{_gte:$df}}, {createdAt:{_lte:$dt}}]}) { total }
  pendingReceipts: receipt(where: {receiptStatus:{id:{_eq:"pendingConfirmation"}}}) { total }
  pendingLines: receiptLine(where: {receiptStatus:{id:{_eq:"pendingConfirmation"}}}) { total }
  topSupplierLines: receiptLine(
    where: {
      _and: [
        { createdAt: { _gte: $df } }
        { createdAt: { _lte: $dt } }
      ]
    }
    first: 1000
    orderBy: [{ field: createdAt, direction: desc }]
  ) {
    edges {
      node {
        receipt {
          order {
            businessPartner {
              name
            }
          }
        }
      }
    }
  }
}

query SHIPKPIs(
  $df: DateTime $dt: DateTime $dfp: DateTime $dtp: DateTime
  $sd: DateTime $ed: DateTime
) {
  shippedCurr: load(where: {_and: [{loadStatus:{id:{_eq:"shipped"}}},{departAt:{_gte:$df}},{departAt:{_lte:$dt}}]}) { total }
  shippedPrev: load(where: {_and: [{loadStatus:{id:{_eq:"shipped"}}},{departAt:{_gte:$dfp}},{departAt:{_lte:$dtp}}]}) { total }
  shortCurr: load(where: {_and: [{loadStatus:{id:{_eq:"shortShipped"}}},{departAt:{_gte:$df}},{departAt:{_lte:$dt}}]}) { total }
  shortPrev: load(where: {_and: [{loadStatus:{id:{_eq:"shortShipped"}}},{departAt:{_gte:$dfp}},{departAt:{_lte:$dtp}}]}) { total }
  activeLoads: load(where: {_and:[{active:{_eq:true}},{loadStatus:{id:{_in:["new","packed","picked"]}}}]}) { total }
  departingToday: load(where: {_and: [{loadStatus:{id:{_in:["new","packed","picked"]}}},{scheduledDepartAt:{_gte:$sd}},{scheduledDepartAt:{_lte:$ed}}]}) { total }
  shippedToday: load(where: {_and: [{loadStatus:{id:{_eq:"shipped"}}},{departAt:{_gte:$sd}},{departAt:{_lte:$ed}}]}) { total }
}

query INVKPIs($now: DateTime, $exp7: DateTime, $exp30: DateTime) {
  totalLots: lot { total }
  expiring7: lot(where: {_and:[{expiresAt:{_gte:$now}},{expiresAt:{_lte:$exp7}},{expiresAt:{_isNull:false}}]}) { total }
  expiring30: lot(where: {_and:[{expiresAt:{_gte:$now}},{expiresAt:{_lte:$exp30}},{expiresAt:{_isNull:false}}]}) { total }
  onHold: inventory(where: {_and:[{active:{_eq:true}},{inventoryStatus:{id:{_in:["hold","qcHold","qcInspect","damaged","mrb"]}}}]}) { total }
  activeInventory: inventory(where: {active:{_eq:true}}) { total }
  damagedMrb: inventory(where: {_and:[{active:{_eq:true}},{inventoryStatus:{id:{_in:["damaged","mrb"]}}}]}) { total }
  lostInventory: inventory(where: {_and:[{active:{_eq:true}},{inventoryStatus:{id:{_eq:"lost"}}}]}) { total }
