query CCKPIs(
  $df: DateTime
  $dfp: DateTime
  $dtp: DateTime
  $now: DateTime
  $endOfMonth: DateTime
) {
  totalCurr: count(where: {
    _and: [
      { scheduledStartAt: { _gte: $df } }
      { scheduledStartAt: { _lte: $endOfMonth } }
    ]
  }) { total }
  totalPrev: count(where: {
    _and: [
      { scheduledStartAt: { _gte: $dfp } }
      { scheduledStartAt: { _lte: $dtp } }
    ]
  }) { total }
  completedCurr: count(where: {
    _and: [
      { completedAt: { _isNull: false } }
      { completedAt: { _gte: $df } }
      { completedAt: { _lte: $endOfMonth } }
    ]
  }) { total }
  completedPrev: count(where: {
    _and: [
      { completedAt: { _isNull: false } }
      { completedAt: { _gte: $dfp } }
      { completedAt: { _lte: $dtp } }
    ]
  }) { total }
  inProgress: count(where: {
    _and: [
      { actualStartAt: { _isNull: false } }
      { completedAt: { _isNull: true } },
      { countStatusId: { _in: ["started"]}}
    ]
  }) { total }
  overdue: count(where: {
    _and: [
      { scheduledStartAt: { _lte: $now } }
      { completedAt: { _isNull: true } }
      { countStatus: { id: { _in: ["new", "started", "countCompleted"] } } }
    ]
  }) { total }
  financeApproval: count(where: {
    countStatus: { id: { _eq: "pendingFinanceApproval" } }
  }
  first: 1) { total }
}

