data.transform:
(
  $ordFulCurr  := $.ordFulCurr.total;
  $ordTotCurr  := $.ordTotCurr.total;
  $ordFulPrev  := $.ordFulPrev.total;
  $ordTotPrev  := $.ordTotPrev.total;
  $relFulCurr  := $.relFulCurr.total;
  $relTotCurr  := $.relTotCurr.total;
  $relFulPrev  := $.relFulPrev.total;
  $relTotPrev  := $.relTotPrev.total;
  $shippedCurr := $.shippedCurr.total;
  $shippedPrev := $.shippedPrev.total;
  $shortCurr   := $.shortCurr.total;
  $shortPrev   := $.shortPrev.total;
  $rcvPendCurr := $.rcvPendCurr.total;
  $rcvPendPrev := $.rcvPendPrev.total;
  $expLots7    := $.expLots7.total;
  $expLots30   := $.expLots30.total;

  $trendFn := function($c,$p,$h) {(
    $d := $c - $p; $pct := $p > 0 ? $round($d/$p*100) : 0;
    $a := $d > 0 ? "▲" : ($d < 0 ? "▼" : "▶");
    $pct != 0 ? $a & " " & $string($pct < 0 ? -$pct : $pct) & "%" : "▶ 0%")
  };

  $fulfillRateCurr := $ordTotCurr > 0 ? $round($ordFulCurr / $ordTotCurr * 100) : 0;
  $fulfillRatePrev := $ordTotPrev > 0 ? $round($ordFulPrev / $ordTotPrev * 100) : 0;
  $fillRateCurr    := $relTotCurr > 0 ? $round($relFulCurr / $relTotCurr * 100) : 0;
  $fillRatePrev    := $relTotPrev > 0 ? $round($relFulPrev / $relTotPrev * 100) : 0;

  $fulfillColor := $fulfillRateCurr >= 75 ? "#1D9E7555" : ($fulfillRateCurr >= 50 ? "#F5C51855" : "#E5393555");
  $fillColor    := $fillRateCurr >= 90 ? "#1D9E7555" : ($fillRateCurr >= 75 ? "#F5C51855" : "#E5393555");
  $shipColor    := "#534AB755";
  $shortColor   := $shortCurr = 0 ? "#1D9E7555" : ($shortCurr <= 3 ? "#F5C51855" : "#E5393555");
  $rcvColor     := $rcvPendCurr = 0 ? "#1D9E7555" : ($rcvPendCurr <= 10 ? "#F5C51855" : "#E5393555");
  $lotsColor    := $expLots7 = 0 ? "#1D9E7555" : ($expLots7 <= 10 ? "#F5C51855" : "#E5393555");

  $redCount    := $count([$fulfillColor,$fillColor,$shortColor,$rcvColor,$lotsColor][$= "#E5393555"]);
  $yellowCount := $count([$fulfillColor,$fillColor,$shortColor,$rcvColor,$lotsColor][$= "#F5C51855"]);
  $healthStatus := $redCount > 0 ? "⚠ Critical" : ($yellowCount > 0 ? "◆ Needs Attention" : "✓ Good");

  {
    "kpi": {
      "fulfillMd":    $string($fulfillRateCurr) & "%",
      "fulfillTrend": $trendFn($fulfillRateCurr, $fulfillRatePrev, true),
      "fillMd":       $string($fillRateCurr) & "%",
      "fillTrend":    $trendFn($fillRateCurr, $fillRatePrev, true),
      "shipMd":       $string($shippedCurr),
      "shipTrend":    $trendFn($shippedCurr, $shippedPrev, true),
      "shortMd":      $string($shortCurr),
      "shortTrend":   $trendFn($shortCurr, $shortPrev, false),
      "rcvMd":        $string($rcvPendCurr),
      "rcvTrend":     $trendFn($rcvPendCurr, $rcvPendPrev, false),
      "lotsMd":       $string($expLots7),
      "fulfillColor": $fulfillColor,
      "fillColor":    $fillColor,
      "shipColor":    $shipColor,
      "shortColor":   $shortColor,
      "rcvColor":     $rcvColor,
      "lotsColor":    $lotsColor,
      "healthStatus": $healthStatus,
      "currentMonth": $.periodLabel
    }
  }
)

